"""Load configuration from files and strings."""

import os

from miniconf.errors import ConfigError
from miniconf.parser import parse_lines

INCLUDE_DIRECTIVE = "@include"


def _read_lines(path):
    with open(path, "r", encoding="utf-8") as fh:
        return fh.read().splitlines()


def _expand(path, lines, stack):
    """Return ``lines`` (read from ``path``) with ``@include`` lines expanded."""
    stack = stack + [os.path.realpath(path)]
    base = os.path.dirname(os.path.abspath(path))
    expanded = []
    for lineno, raw in enumerate(lines, start=1):
        parts = raw.split(None, 1)
        if not parts or parts[0] != INCLUDE_DIRECTIVE:
            expanded.append(raw)
            continue
        target = parts[1].strip() if len(parts) > 1 else ""
        if not target:
            raise ConfigError(
                "{} line {}: @include requires a path".format(path, lineno)
            )
        target = os.path.join(base, os.path.expanduser(target))
        real = os.path.realpath(target)
        if real in stack:
            raise ConfigError(
                "include cycle detected: {}".format(" -> ".join(stack + [real]))
            )
        try:
            included = _read_lines(target)
        except FileNotFoundError:
            raise ConfigError(
                "{} line {}: included file not found: {}".format(
                    path, lineno, target
                )
            )
        except OSError as exc:
            raise ConfigError(
                "{} line {}: cannot read included file {}: {}".format(
                    path, lineno, target, exc
                )
            )
        expanded.extend(_expand(target, included, stack))
    return expanded


def load(path):
    """Read and parse the configuration file at ``path``.

    ``@include <path>`` lines are expanded in place with the contents of the
    referenced file, resolved relative to the including file's directory.
    """
    lines = _read_lines(path)
    return parse_lines(_expand(path, lines, []))


def loads(text):
    """Parse configuration from a string."""
    return parse_lines(text.splitlines())
